-- Bike Log v0.2.0 (schema revision 0005), demo/sample data made by that version's own code.
BEGIN TRANSACTION;
CREATE TABLE alembic_version (
	version_num VARCHAR(32) NOT NULL, 
	CONSTRAINT alembic_version_pkc PRIMARY KEY (version_num)
);
INSERT INTO "alembic_version" VALUES('0005');
CREATE TABLE app_setting (
	"key" VARCHAR(64) NOT NULL, 
	value TEXT NOT NULL, 
	PRIMARY KEY ("key")
);
INSERT INTO "app_setting" VALUES('demo_mode','1');
CREATE TABLE bike (
	id INTEGER NOT NULL, 
	uuid VARCHAR(36) NOT NULL, 
	name TEXT NOT NULL, 
	maker TEXT, 
	model TEXT, 
	year INTEGER, 
	status VARCHAR(16) NOT NULL, 
	strava_gear_id VARCHAR(32), 
	notes TEXT, 
	created_at VARCHAR(20) NOT NULL, 
	updated_at VARCHAR(20) NOT NULL, purchase_price_cents INTEGER, purchase_date VARCHAR(10), 
	PRIMARY KEY (id), 
	CONSTRAINT ck_bike_status CHECK (status IN ('ACTIVE','RETIRED')), 
	UNIQUE (name), 
	UNIQUE (strava_gear_id), 
	UNIQUE (uuid)
);
