            FOR EACH ROW WHEN NEW.tire_setup IS NOT NULL AND NEW.tire_setup NOT IN ('TUBE','TUBELESS','TUBULAR')
            BEGIN SELECT RAISE(ABORT, 'INVALID: component.tire_setup must be TUBE, TUBELESS or TUBULAR'); END;
