            FOR EACH ROW WHEN NEW.requires_setup IS NOT NULL AND NEW.requires_setup NOT IN ('TUBE','TUBELESS','TUBULAR')
            BEGIN SELECT RAISE(ABORT, 'INVALID: service_rule.requires_setup must be TUBE, TUBELESS or TUBULAR'); END;
CREATE TRIGGER trg_service_rule_requires_setup_update BEFORE UPDATE ON service_rule
            FOR EACH ROW WHEN NEW.requires_setup IS NOT NULL AND NEW.requires_setup NOT IN ('TUBE','TUBELESS','TUBULAR')
            BEGIN SELECT RAISE(ABORT, 'INVALID: service_rule.requires_setup must be TUBE, TUBELESS or TUBULAR'); END;
